// Tests for the pricing seed snapshot (model_catalog_data_gen.go) and the
// models-table projection helpers (model_catalog_data.go). The row count pins
// the current snapshot; the snapshot is generated by
// pricing.TestGenerateSeedCatalog from catalogdata/*.json — update the data
// rows and the pinned count in one change.

package schema

import (
	"context"
	"encoding/json"
	"sort"
	"strings"
	"testing"
	"time"
)

// nodeModelCatalogCompare mirrors compareProviderModels in Node
// model-pricing.service.ts (catalog order asc when both defined, then release
// date desc with nils last, then model asc).
func nodeModelCatalogCompare(left, right modelCatalogSeedRow) int {
	if left.CatalogOrder != nil && right.CatalogOrder != nil && *left.CatalogOrder != *right.CatalogOrder {
		if *left.CatalogOrder < *right.CatalogOrder {
			return -1
		}
		return 1
	}
	switch {
	case left.ReleaseDate != nil && right.ReleaseDate != nil && *left.ReleaseDate != *right.ReleaseDate:
		if *left.ReleaseDate > *right.ReleaseDate {
			return -1
		}
		return 1
	case left.ReleaseDate != nil && right.ReleaseDate == nil:
		return -1
	case left.ReleaseDate == nil && right.ReleaseDate != nil:
		return 1
	}
	return strings.Compare(left.Model, right.Model)
}

func TestModelCatalogSeedRowsPinnedCount(t *testing.T) {
	// 212 rows（当前 HEAD 快照钉值）：217 rows from the evidence batch +
	// gemini-3.5-live-translate-preview + 3 openai realtime/audio additions
	// (gpt-realtime-mini / gpt-audio / gpt-audio-mini missed by the completion
	// batch)（gemini-3.1-flash-tts-preview legacy TTS at co107 /
	// veo-3.1-fast-generate-preview video row / gemini-3.1-flash-lite-image
	// image row at co103）。The evidence batch also reverted gemini-omni-1.1-
	// flash to the official $1.50 input / $9.00 text output, and moved
	// paraformer-v2 to the international-site USD price $0.000012/second
	// (static layer only)。2026-10-17 口径核对批五家回正（行数不变）+ 2025 前
	// 模型清理批两阶段 -24 行 + 缺口补录 +3 + 火山 ASR 承接 +1 + 缺口补录
	// 第二批 +8 + 方舟全能力实测 +1 → 210；同日火山方舟 +2（视频 1 行 +
	// 图像 1 行，快照数据本体冻结）→ 212；同日全能力覆盖批终态（并发协调后合并口径）：+1 vision 向量行（doubao-embedding-vision-251215，现役唯一向量模型）−2 官方退役死行（doubao-embedding-large-text-250515 文本向量系 Retiring、/v1/embeddings 面 404 实证；doubao-seededit-3-0-i2i-250628 官方 /api/v3/models 列表 status=Shutdown，现役图生图由 seedream 4.0/5.0 原生 image 参数承接）→ 211；同日流式语音桥接批 +1（volcengine seed-tts-2.0，按字符 3 元/万字符 ÷7.0）→ 212。models 表口径下全量行落库
	//（disabled 行计入），行数仍等于快照行数。
	if len(modelCatalogSeedRows) != 212 {
		t.Fatalf("model catalog seed rows = %d, want 212 (stale snapshot? rerun the generator from backend-go/projects/gateway/internal/pricing/catalogdata/*.json)", len(modelCatalogSeedRows))
	}
	perProvider := map[string]int{}
	for _, row := range modelCatalogSeedRows {
		perProvider[row.ProviderCode]++
	}
	want := map[string]int{"gpt": 69, "xai": 17, "deepseek": 3, "anthropic": 15, "gemini": 31, "glm": 23, "minimax": 19, "volcengine": 19, "qwen": 16}
	if len(perProvider) != len(want) {
		t.Fatalf("vendor set = %v, want %v", perProvider, want)
	}
	for provider, count := range want {
		if perProvider[provider] != count {
			t.Fatalf("vendor %s rows = %d, want %d", provider, perProvider[provider], count)
		}
	}
}

func TestModelCatalogSeedRowsIdentityAndOrder(t *testing.T) {
	seenModels := map[string]bool{}
	seenIDs := map[string]bool{}
	for _, row := range modelCatalogSeedRows {
		key := row.ProviderCode + "\x00" + row.Model
		if seenModels[key] {
			t.Fatalf("duplicate (vendor, model) %q", key)
		}
		seenModels[key] = true
		wantID := providerModelCatalogID(row.ProviderCode, row.Model)
		if row.ID != wantID {
			t.Fatalf("row id %q does not match providerModelCatalogId %q", row.ID, wantID)
		}
		if seenIDs[row.ID] {
			t.Fatalf("duplicate id %q", row.ID)
		}
		seenIDs[row.ID] = true
		if row.Source == "" {
			t.Fatalf("row %q has empty source", row.ID)
		}
		if !jsonValidString(row.SupportedAPIProtocolsJSON) {
			t.Fatalf("row %q has invalid supported_api_protocols_json", row.ID)
		}
		if !jsonValidString(row.ServiceTierPricesJSON) {
			t.Fatalf("row %q has invalid service_tier_prices_json", row.ID)
		}
	}
	// Sortedness holds within each vendor segment (Node sorts
	// listProviderModelPricing per vendor); segments follow the vendor seed
	// order (gpt, xai, deepseek, anthropic, gemini, glm, minimax, volcengine,
	// qwen) instead of a global comparator order.
	segmentStart := 0
	for i := 1; i <= len(modelCatalogSeedRows); i++ {
		if i == len(modelCatalogSeedRows) || modelCatalogSeedRows[i].ProviderCode != modelCatalogSeedRows[segmentStart].ProviderCode {
			for j := segmentStart + 1; j < i; j++ {
				if nodeModelCatalogCompare(modelCatalogSeedRows[j-1], modelCatalogSeedRows[j]) > 0 {
					t.Fatalf("rows for vendor %s not in Node listProviderModelPricing order at index %d: %s > %s", modelCatalogSeedRows[segmentStart].ProviderCode, j, modelCatalogSeedRows[j-1].ID, modelCatalogSeedRows[j].ID)
				}
			}
			segmentStart = i
		}
	}
}

func TestProviderModelCatalogID(t *testing.T) {
	cases := []struct {
		provider, model, want string
	}{
		// Golden values produced by Node providerModelCatalogId.
		{"gpt", "gpt-5.6-sol", "provider_model_gpt_gpt_5_6_sol_69ec47b65152"},
		{"gpt", "gpt-6-astra", "provider_model_gpt_gpt_6_astra_14ec3d68eae1"},
		{"gpt", "gpt-6.1-sol", "provider_model_gpt_gpt_6_1_sol_09b2adf74e3b"},
	}
	for _, testCase := range cases {
		if got := providerModelCatalogID(testCase.provider, testCase.model); got != testCase.want {
			t.Fatalf("providerModelCatalogId(%q, %q) = %q, want %q", testCase.provider, testCase.model, got, testCase.want)
		}
	}
}

func jsonValidString(value string) bool {
	return json.Valid([]byte(value))
}

// TestModelSeedRowStatusShutdownSemantics 锁定内置过期模型的 status 判定
// （原 activeModelCatalogSeedRows shutdown 过滤的方向语义）：shutdown_date 已
// 过（<= 截止日）→ 'disabled'，否则 'active'；全量行都参与投影。
func TestModelSeedRowStatusShutdownSemantics(t *testing.T) {
	var shutdownDate *string
	for i := range modelCatalogSeedRows {
		if modelCatalogSeedRows[i].ShutdownDate != nil {
			shutdownDate = modelCatalogSeedRows[i].ShutdownDate
			break
		}
	}
	if shutdownDate == nil {
		t.Skip("no shutdown dates in snapshot")
	}
	for _, row := range modelCatalogSeedRows {
		if got := modelSeedRowStatus(row, "2000-01-01"); got != modelSeedStatusActive {
			t.Fatalf("row %s: status at 2000-01-01 = %q, want active", row.ID, got)
		}
	}
	expired := 0
	for _, row := range modelCatalogSeedRows {
		want := modelSeedStatusActive
		if row.ShutdownDate != nil && *row.ShutdownDate <= *shutdownDate {
			want = modelSeedStatusDisabled
			expired++
		}
		if got := modelSeedRowStatus(row, *shutdownDate); got != want {
			t.Fatalf("row %s: status at %s = %q, want %q", row.ID, *shutdownDate, got, want)
		}
	}
	if expired == 0 {
		t.Fatalf("shutdown date %s should expire at least one row", *shutdownDate)
	}
}

// TestModelSeedEndpointModesDistribution 锁定 supported_endpoint_modes_json
// 推导的实际分布：mode 集合按协议声明推导、元素唯一且 ASCII 升序，与快照
// 现状的分布计数逐一相符。
func TestModelSeedEndpointModesDistribution(t *testing.T) {
	rows, err := modelSeedTargetRows("2000-01-01")
	if err != nil {
		t.Fatalf("modelSeedTargetRows: %v", err)
	}
	if len(rows) != len(modelCatalogSeedRows) {
		t.Fatalf("projected rows = %d, want %d", len(rows), len(modelCatalogSeedRows))
	}
	distribution := map[string]int{}
	for _, row := range rows {
		var modes []string
		if err := json.Unmarshal([]byte(row.SupportedEndpointModesJSON), &modes); err != nil {
			t.Fatalf("row %s modes json: %v", row.ID, err)
		}
		if len(modes) == 0 {
			t.Fatalf("row %s derived empty mode set", row.ID)
		}
		if !sort.StringsAreSorted(modes) {
			t.Fatalf("row %s modes not ASCII sorted: %v", row.ID, modes)
		}
		seen := map[string]bool{}
		for _, mode := range modes {
			if seen[mode] {
				t.Fatalf("row %s duplicate mode %q", row.ID, mode)
			}
			seen[mode] = true
		}
		distribution[row.SupportedEndpointModesJSON]++
	}
	want := map[string]int{
		`["audio_speech"]`:             17,
		`["audio_transcription_json"]`: 7,
		`["chat_json","chat_sse"]`:     43,
		`["chat_json","chat_sse","count_tokens","generate_content_json","generate_content_sse"]`:                                        1,
		`["chat_json","chat_sse","count_tokens","generate_content_json","generate_content_sse","interactions_json","interactions_sse"]`: 11,
		`["chat_json","chat_sse","messages_json","messages_sse","responses_json","responses_sse"]`:                                      3,
		`["chat_json","chat_sse","responses_json","responses_sse"]`:                                                                     42,
		`["embed_content"]`: 3,
		`["generate_content_json","generate_content_sse"]`: 5,
		`["images_json"]`: 13,
		`["images_json","responses_json","responses_sse"]`:            3,
		`["message_token_counting","messages_json","messages_sse"]`:   15,
		`["realtime_session"]`:                                        13,
		`["responses_json","responses_sse"]`:                          12,
		`["video_cancel","video_content","video_create","video_get"]`: 24,
	}
	if len(distribution) != len(want) {
		t.Fatalf("mode set kinds = %d, want %d\ngot: %v", len(distribution), len(want), distribution)
	}
	for modesJSON, wantCount := range want {
		if distribution[modesJSON] != wantCount {
			t.Fatalf("mode set %s rows = %d, want %d", modesJSON, distribution[modesJSON], wantCount)
		}
	}
	// 身份与可见性按投影规则搬运：抽查首行（gpt-6.1-sol）。
	first := rows[0]
	if first.VendorCode != "gpt" || first.PublicModel != "gpt-6.1-sol" || first.UpstreamModel != "gpt-6.1-sol" {
		t.Fatalf("first projected row identity = %s/%s/%s", first.VendorCode, first.PublicModel, first.UpstreamModel)
	}
	if first.Status != modelSeedStatusActive || !first.CatalogVisible {
		t.Fatalf("first projected row status/visible = %s/%v", first.Status, first.CatalogVisible)
	}
}

// TestModelSeedTableRowsMatchProjection locks the seed's own output to the
// models-table projection: fresh ensure+seed writes every snapshot row
// （disabled 行计入）, the disabled subset equals the shutdown-expired rows of
// the same pinned clock, and repeated seeds keep the count stable. The gateway
// storage bootstrap test routes the same count through
// bootstrap.SQLiteSeedResult.ModelCatalogRows; maintenance internal is not
// importable across modules.
func TestModelSeedTableRowsMatchProjection(t *testing.T) {
	db := openSeedTestDatabase(t)
	ctx := context.Background()
	result, err := SeedSQLiteDefaults(ctx, db, SeedOptions{Now: func() time.Time { return sqliteSeedTestClock }})
	if err != nil {
		t.Fatalf("seed sqlite defaults: %v", err)
	}
	asOf := sqliteSeedTestClock.UTC().Format("2006-01-02")
	projection, err := modelSeedTargetRows(asOf)
	if err != nil {
		t.Fatalf("modelSeedTargetRows: %v", err)
	}
	if result.ModelCatalogRows != len(projection) {
		t.Fatalf("seed ModelCatalogRows = %d, want projection size %d", result.ModelCatalogRows, len(projection))
	}
	if result.ModelCatalogRows != len(modelCatalogSeedRows) {
		t.Fatalf("seed ModelCatalogRows = %d, want full snapshot size %d", result.ModelCatalogRows, len(modelCatalogSeedRows))
	}
	var tableRows int
	if err := db.QueryRowContext(ctx, "SELECT count(*) FROM models").Scan(&tableRows); err != nil {
		t.Fatalf("query models: %v", err)
	}
	if tableRows != result.ModelCatalogRows {
		t.Fatalf("models rows = %d, want %d (fresh seed, upsert only)", tableRows, result.ModelCatalogRows)
	}
	expired := 0
	for _, source := range modelCatalogSeedRows {
		if modelSeedRowStatus(source, asOf) == modelSeedStatusDisabled {
			expired++
		}
	}
	var disabledRows int
	if err := db.QueryRowContext(ctx, "SELECT count(*) FROM models WHERE status = 'disabled'").Scan(&disabledRows); err != nil {
		t.Fatalf("query disabled models: %v", err)
	}
	if disabledRows != expired {
		t.Fatalf("disabled models rows = %d, want %d (shutdown expired at %s)", disabledRows, expired, asOf)
	}
	second, err := SeedSQLiteDefaults(ctx, db, SeedOptions{Now: func() time.Time { return sqliteSeedTestClock }})
	if err != nil {
		t.Fatalf("second seed (idempotency): %v", err)
	}
	if second.ModelCatalogRows != result.ModelCatalogRows {
		t.Fatalf("second seed ModelCatalogRows = %d, want %d", second.ModelCatalogRows, result.ModelCatalogRows)
	}
}
